def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows and columns are uniform and share the same color.
    row_colors = {r: grid[r][0] for r in range(h)
                  if all(x == grid[r][0] for x in grid[r])}
    col_colors = {c: grid[0][c] for c in range(w)
                  if all(grid[r][c] == grid[0][c] for r in range(h))}
    sep_color = next((v for v in row_colors.values()
                      if v in col_colors.values()), None)

    sep_rows = {r for r, v in row_colors.items() if v == sep_color}
    sep_cols = {c for c, v in col_colors.items() if v == sep_color}

    def bands(size, separators):
        result, start = [], 0
        for i in sorted(separators):
            if start < i:
                result.append(list(range(start, i)))
            start = i + 1
        if start < size:
            result.append(list(range(start, size)))
        return result

    row_bands = bands(h, sep_rows)
    col_bands = bands(w, sep_cols)

    counts = {}
    for rband in row_bands:
        for cband in col_bands:
            for r in rband:
                for c in cband:
                    value = grid[r][c]
                    counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    foreground = min(counts, key=counts.get)

    return [
        [1 if sum(grid[r][c] == foreground
                  for r in rband for c in cband) == 2 else background
         for cband in col_bands]
        for rband in row_bands
    ]
